    receive() external payable {}

    function run(address newOwner) public {
        require(newOwner != address(0));

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        bool success;
        bool ret = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = ret;
        }
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

