contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        vm.assume(newOwner != address(0));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool success;
        try c.setOwner(newOwner) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue((success && ownerAfter == newOwner) ||
            (!success && ownerAfter == ownerBefore));
    }

